package com.quantumtemplates

import com.intellij.codeInsight.hint.HintManager
import com.intellij.openapi.actionSystem.ActionUpdateThread
import com.intellij.openapi.actionSystem.AnAction
import com.intellij.openapi.actionSystem.AnActionEvent
import com.intellij.openapi.actionSystem.CommonDataKeys
import com.intellij.openapi.project.DumbService

// Text, description and shortcut are declared in plugin.xml.
// Jumps from a symbol generated by the Quantum codegen to its declaration in a .qtn file (see QtnLookup).
class GoToQtnDeclarationAction : AnAction() {

    override fun getActionUpdateThread() = ActionUpdateThread.BGT

    override fun update(e: AnActionEvent) {
        e.presentation.isEnabledAndVisible = e.project != null && e.getData(CommonDataKeys.EDITOR) != null
    }

    override fun actionPerformed(e: AnActionEvent) {
        val project = e.project ?: return
        val editor = e.getData(CommonDataKeys.EDITOR) ?: return

        if (DumbService.isDumb(project)) {
            HintManager.getInstance().showErrorHint(editor, "QTN lookup is unavailable while indexing")
            return
        }

        val offset = QtnLookup.targetOffset(editor, e.inputEvent)
        val word = QtnLookup.identifierAt(editor.document.charsSequence, offset)
        if (word == null) {
            HintManager.getInstance().showErrorHint(editor, "No identifier at caret")
            return
        }

        val target = QtnLookup.find(project, word)
        if (target == null) {
            HintManager.getInstance().showErrorHint(editor, "No QTN declaration found for '$word'")
            return
        }

        target.navigate(project)
    }
}
